{
  "name": "串口流接口组件",
  "name_en": "Serial Stream Interface Component",
  "manufacturer": "",
  "description": "用于实验系统中的非物理串口通信组件，提供对串行端口的数据写入、读取和连接关闭功能，作为上层程序与各类串口设备交换字节流的通用接口。",
  "description_en": "A non-physical serial communication component used in laboratory systems. It provides generic byte-stream write, read, and close operations over a serial port for higher-level software to communicate with serial devices.",
  "actions": [
    {
      "action_name": "auto-write",
      "description": "向串口流写入数据。",
      "description_en": "Write data to the serial stream."
    },
    {
      "action_name": "auto-read",
      "description": "从串口流读取指定长度的数据。",
      "description_en": "Read a specified amount of data from the serial stream."
    },
    {
      "action_name": "auto-close",
      "description": "关闭串口流连接。",
      "description_en": "Close the serial stream connection."
    }
  ],
  "tag_hints": [
    "serial communication",
    "byte stream I/O",
    "instrument connectivity",
    "RS-232/serial port",
    "generic transport layer"
  ]
}

